// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 blockNum) public {
        blockNum = bound(blockNum, 1, 1e6);
        vm.roll(blockNum);
        vm.warp(1);

        address actor = makeAddr("actor");
        uint256 payment = 10 ether;
        vm.deal(actor, payment);

        vm.prank(actor);
        (bool ok,) = address(c).call{value: payment}("");

        bool isMultiple = (blockNum % 15 == 0);
        bool balanceIsZero = address(c).balance == 0;

        assertTrue(!(ok && (isMultiple ? !balanceIsZero : balanceIsZero)));
    }
}
